// Embeds shared/quicklook/quicklook.js in lib/src/quicklook_js.g.dart, so the SDK can install it
// synchronously without asking apps to add a script tag.
//
// Run from the package directory:
//   dart run tool/embed_js.dart          regenerate after changing quicklook.js
//   dart run tool/embed_js.dart --check  exit 1 if the generated file is out of date
import 'dart:io';

final source = File('../../shared/quicklook/quicklook.js');
final target = File('lib/src/quicklook_js.g.dart');

String generate(String js) {
  if (js.contains("'''")) throw FormatException("quicklook.js can't be embedded: it contains '''");
  final version = RegExp(r'var VERSION = "([^"]+)";').firstMatch(js)?.group(1);
  if (version == null) throw FormatException('quicklook.js has no var VERSION = "...";');
  return '// GENERATED by tool/embed_js.dart from shared/quicklook/quicklook.js. Do not edit.\n'
      '\n'
      "const quickLookVersion = '$version';\n"
      '\n'
      "const quickLookJs = r'''\n$js''';\n";
}

void main(List<String> args) {
  final expected = generate(source.readAsStringSync());
  if (args.contains('--check')) {
    if (!target.existsSync() || target.readAsStringSync() != expected) {
      stderr.writeln('${target.path} is out of date: run dart run tool/embed_js.dart');
      exit(1);
    }
    return;
  }
  target.writeAsStringSync(expected);
  stdout.writeln('Wrote ${target.path}');
}
